{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a highly lipophilic diester plasticizer, was almost completely bioavailable in humans after oral dosing, supporting that very lipophilic ester-type molecules can achieve F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a long-chain dodecyl ester of a dipeptide-like structure, showed about 60% oral bioavailability in healthy human volunteers, supporting high F for lipophilic ester/amide molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, showed >60% oral bioavailability in humans, supporting high F for lipophilic ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "DEHP, a lipophilic diester, had about 25% oral bioavailability in human volunteers, which is above the 20% threshold and supports high F for very lipophilic esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain ester prodrug, had an absolute oral bioavailability of 85 ± 15% in children, supporting high F for lipophilic ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, an ester prodrug with polar sugar, guanidine, and carboxylate groups, had only 15% oral bioavailability; its polar character is not shared by the query, so this is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic ester/lactone/amide molecule. Although physicochemical properties suggest solubility concerns, the preponderance of experimental evidence from structurally related lipophilic esters and ester prodrugs shows oral bioavailability at or above 20%, often much higher. The only sub-20% analogue is much more polar and does not transfer well. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "Morgan similarities between the query and evidence molecules are low (0.18-0.24), limiting transferability.",
    "The high logP and low predicted solubility may require formulation or food effects to achieve the observed high bioavailability of analogues.",
    "The metabolic and chemical stability of the beta-lactone and ester/amide linkages in the gastrointestinal tract is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

